// Pieces in the womenswear list that are cut for everyone.
const UNISEX = new Set(['p-trainers', 'p-leather-belt']);
for (const p of CATALOGUE) p.gender = UNISEX.has(p.id) ? 'unisex' : p.gender ?? 'women';

const tierOf = (brand: string) => (Object.keys(TIER_BRANDS) as Product['tier'][]).find((t) => TIER_BRANDS[t].includes(brand)) ?? 'Affordable';
CATALOGUE.push(...menswear(tierOf));
// Depth: each brand filled out to a browsable range (see catalogueExtra.ts).
CATALOGUE.push(...EXTRA_CATALOGUE);

export const productById = (id: string) => CATALOGUE.find((p) => p.id === id);

/** Does this piece belong in this department? Unisex pieces show in both. */
export const forDepartment = (p: Product, shopsFor?: ShopsFor) => !shopsFor || (p.gender ?? 'women') === 'unisex' || (p.gender ?? 'women') === shopsFor;

/** The brands of a tier that actually stock this department, in list order. */
export const tierBrandsFor = (tier: Product['tier'], products: Product[]) => {
  const have = new Set(products.filter((p) => p.tier === tier).map((p) => p.brand));
  return TIER_BRANDS[tier].filter((b) => have.has(b));
};

/* ---------------------------------------------------------------------------------------------- */
/* Illustrative price model (stand-in for a live price-comparison feed)                            */
/* ---------------------------------------------------------------------------------------------- */

const RETAILERS: Record<Product['tier'], { retail: string[]; resale: string[] }> = {
  Affordable: { retail: ['ASOS', 'John Lewis', 'Next'], resale: ['Vinted', 'Depop'] },
  Attainable: { retail: ['Selfridges', 'John Lewis', 'Harvey Nichols'], resale: ['Vestiaire Collective', 'Vinted'] },
  Aspirational: { retail: ['Mytheresa', 'Harrods', 'Selfridges'], resale: ['Vestiaire Collective', 'The RealReal'] },
};

function seeded(id: string) {
  let h = 2166136261;
  for (const c of id) h = Math.imul(h ^ c.charCodeAt(0), 16777619);
  return () => {
    h = Math.imul(h ^ (h >>> 15), 2246822507);
    h = Math.imul(h ^ (h >>> 13), 3266489909);
    return ((h ^= h >>> 16) >>> 0) / 4294967296;
  };
}

const roundPrice = (n: number) => (n >= 200 ? Math.round(n) : Math.round(n * 100) / 100);

export function priceCheckFor(p: Product): PriceCheck {
  const rnd = seeded(p.id);
  const r = RETAILERS[p.tier];
  const offers: Offer[] = [
    { retailer: p.brand, kind: 'retail', condition: 'New', price: p.price, delivery: p.tier === 'Affordable' ? 'Free over £50' : 'Free delivery', url: p.sourceUrl },
    ...r.retail.filter((x) => x !== p.brand).slice(0, 2).map((retailer) => ({
      retailer,
      kind: 'retail' as const,
      condition: 'New',
      price: roundPrice(p.price * (0.86 + rnd() * 0.22)),
      delivery: rnd() > 0.5 ? 'Free delivery' : '£4.95 delivery',
    })),
    ...r.resale.map((retailer, i) => ({
      retailer,
      kind: 'resale' as const,
      condition: i === 0 ? 'Pre-owned · Very good' : 'Pre-owned · Good',
      price: roundPrice(p.price * (0.38 + rnd() * 0.24)),
      delivery: 'Ships in 2–4 days',
    })),
  ];
  offers.sort((a, b) => a.price - b.price);
  const typical = p.price * (0.84 + rnd() * 0.36);
  const typicalLow = roundPrice(typical * 0.94);
  const typicalHigh = roundPrice(typical * 1.06);
  const verdict = p.price < typicalLow ? 'good' : p.price > typicalHigh ? 'high' : 'typical';
  return { productId: p.id, verdict, typicalLow, typicalHigh, best: offers[0], offers, illustrative: true };
}

/** Cheapest new offer, used for "buy the whole look for less". */
export const bestNewPrice = (check: PriceCheck) => Math.min(...check.offers.filter((o) => o.kind === 'retail').map((o) => o.price));
